steps.script:
var cg = GameState.get_unit("U_CUSTODIAN_GUARD_A")
cg["flags"].merge({"fights_first": true, "charged_this_turn": true}, true)
for m in cg.models:
	m["wounds"] = 99
	m["current_wounds"] = 99
for uid in ["U_BOYZ_B", "U_WARBOSS_A"]:
	GameState.get_unit(uid)["flags"]["waaagh_active"] = true
return true

var dl = tree.root.get_node("StratagemDialog")
var sc = dl.get_node("Content/StratScroll")
var view = sc.get_global_rect()
var n = 0
var shown = 0
for card in sc.get_node("StratList").get_children():
	var b = card.get_node_or_null("Buttons")
	if b == null:
		continue
	for btn in b.get_children():
		if btn is Button and btn.visible:
			n += 1
			var r = btn.get_global_rect()
			if r.position.y >= view.position.y - 0.5 and r.end.y <= view.end.y + 0.5:
				shown += 1
var vp = tree.root.get_visible_rect().size
var on_screen = dl.position.y >= 0 and dl.position.y + dl.size.y <= vp.y
return "%d/%d on_screen=%s" % [shown, n, str(on_screen)]

var dock = tree.root.find_child("FightResolutionDock", true, false)
if dock == null or not dock.visible:
	return "no dock"
return [dock.status_label.text.contains("Waiting for Player 2's stratagem decision"), dock.primary_button.text]

var p = tree.root.get_node("Main")._reactive_stratagem_overlay_panel
var r = p.get_global_rect()
return [p.visible, r.position.y >= 100.0, r.end.y <= 260.0]

var p = PhaseManager.get_current_phase_instance()
var rolls = 0
var kept = 0
var ok = true
for d in p.dice_log:
	if typeof(d) == TYPE_DICTIONARY and str(d.get("context", "")) == "ork11e_fight_on_death":
		rolls += 1
		if int(d.get("modifier", 0)) != 1:
			ok = false
		if d.get("kept", false):
			kept += 1
		if bool(d.get("kept", false)) != (int(d.rolls_raw[0]) + 1 >= 4):
			ok = false
var dead = 0
var zero = 0
for m in GameState.get_unit("U_BOYZ_B").models:
	if not m.get("alive", true):
		dead += 1
	elif int(m.get("current_wounds", 1)) <= 0:
		zero += 1
var pend = GameState.get_unit("U_BOYZ_B").flags.get("ork11e_fod_pending", [])
print("OINB scenario: rolls=%d kept=%d dead=%d zero=%d pending=%s" % [rolls, kept, dead, zero, str(pend)])
return ok and rolls > 0 and rolls == dead + zero and kept == zero and pend.size() == kept

var u = GameState.get_unit("U_BOYZ_B")
for m in u.models:
	if m.get("alive", true) and int(m.get("current_wounds", 1)) <= 0:
		return false
return u.flags.get("ork11e_fod_pending", []).is_empty()
